"use client"

import { useEffect, useState } from "react"
import { DashboardNav } from "@/components/dashboard-nav"
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Apple, Plus } from "lucide-react"
import Link from "next/link"

interface MealPlan {
  id: string
  title: string
  description: string | null
  start_date: string
  end_date: string | null
  daily_calories: number | null
  daily_protein: number | null
  daily_carbs: number | null
  daily_fats: number | null
}

export default function MealPlansPage() {
  const [mealPlans, setMealPlans] = useState<MealPlan[]>([])
  const [isLoading, setIsLoading] = useState(true)

  useEffect(() => {
    const fetchMealPlans = async () => {
      try {
        // user_id الحقيقي لازم يجي من session أو أي طريقة تعرفي المستخدم الحالي
        const userId = "707706fa-1d96-4c86-93cf-ae6192e97199" // مؤقت للتجربة

        const res = await fetch(`/api/get-meal-plans?user_id=${userId}`)
        const data = await res.json()
        setMealPlans(data.mealPlans || [])
      } catch (err) {
        console.error(err)
      } finally {
        setIsLoading(false)
      }
    }

    fetchMealPlans()
  }, [])

  if (isLoading) return <p className="p-6">Loading...</p>

  return (
    <div className="flex h-screen">
      <DashboardNav />
      <main className="flex-1 overflow-auto bg-background">
        <div className="container mx-auto p-6 space-y-6">

          <div className="flex justify-between items-center">
            <div>
              <h1 className="text-3xl font-bold">Meal Plans</h1>
              <p className="text-muted-foreground mt-1">Track your nutrition and manage meal plans</p>
            </div>
            <Button>
              <Plus className="mr-2 h-4 w-4" />
              Log Food
            </Button>
          </div>

          <div>
            <h2 className="text-xl font-semibold mb-4">Your Meal Plans</h2>
            {mealPlans.length > 0 ? (
              <div className="grid md:grid-cols-2 gap-4">
                {mealPlans.map((plan) => (
                  <Card key={plan.id}>
                    <CardHeader>
                      <CardTitle className="flex items-center gap-2">
                        <Apple className="h-5 w-5" />
                        {plan.title}
                      </CardTitle>
                      <CardDescription>{plan.description}</CardDescription>
                    </CardHeader>
                    <CardContent className="space-y-3">
                      <div className="text-sm space-y-1">
                        <div className="flex justify-between">
                          <span className="text-muted-foreground">Calories:</span>
                          <span className="font-semibold">{plan.daily_calories || 0} kcal</span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-muted-foreground">Protein:</span>
                          <span className="font-semibold">{plan.daily_protein || 0} g</span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-muted-foreground">Carbs:</span>
                          <span className="font-semibold">{plan.daily_carbs || 0} g</span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-muted-foreground">Fats:</span>
                          <span className="font-semibold">{plan.daily_fats || 0} g</span>
                        </div>
                      </div>
                      <div className="pt-2">
                        <p className="text-xs text-muted-foreground">
                          {new Date(plan.start_date).toLocaleDateString()} -{" "}
                          {plan.end_date ? new Date(plan.end_date).toLocaleDateString() : "Ongoing"}
                        </p>
                      </div>
                      <Button variant="outline" className="w-full bg-transparent">
                        View Details
                      </Button>
                    </CardContent>
                  </Card>
                ))}
              </div>
            ) : (
              <Card>
                <CardContent className="py-12 text-center">
                  <Apple className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
                  <h3 className="font-semibold mb-2">No meal plans yet</h3>
                  <p className="text-sm text-muted-foreground mb-6">
                    Get a personalized meal plan from your nutritionist
                  </p>
                  <Link href="/messages/new">
                    <Button>Contact a Nutritionist</Button>
                  </Link>
                </CardContent>
              </Card>
            )}
          </div>
        </div>
      </main>
    </div>
  )
}
